function resolveIconId(raw) {
  const key = String(raw || '')
    .trim()
    .toLowerCase();
  if (BADGE_ICONS[key]) return key;
  if (BADGE_ALIASES[key]) return BADGE_ALIASES[key];
  return '01_code_brackets';
}

function getBadgeSvg(raw) {
  return BADGE_ICONS[resolveIconId(raw)] || BADGE_ICONS['01_code_brackets'];
}

module.exports = { BADGE_ICONS, BADGE_ALIASES, resolveIconId, getBadgeSvg };
